-- ── BILI-DES-050 · 零基础学UI设计：即时设计软件教学【酸梅干超人出品】 ──

INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1ns4y1d7hc', 'course-bili-bv1ns4y1d7hc', '100001', '0', 'BILI-DES-050', 'course-category-design', 'instructor-bili-393337657', '零基础学UI设计：即时设计软件教学【酸梅干超人出品】', '8 讲完整课程 · 3 小时 50 分钟', '零基础学UI设计：即时设计软件教学【酸梅干超人出品】。共 8 讲，累计 3.8 小时，由 酸梅干超人的电话亭 讲解，章节结构完整，可直接在课程播放器中观看。', '内容更多更全！本期课程讲解的是完全免费的国内新兴设计工具——即时设计，本地化网络、全中文还是能很好的吸引中国UI设计师，如果因为Figma英文和翻墙而望而却步的同学，可以使用下这款工具。想要下载使用的同学去即时设计官网即可下载，支持mac、windows、网页端等。回复“即时设计”获取 最后，希望国内工具越做越好～噶油～ 课程结构：共 1 章 8 讲，累计时长 3 小时 50 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握设计软件的核心操作与高效工作流","理解版式、色彩、字体与视觉层级的基本原理","独立完成一套可放入作品集的完整设计项目","建立从需求沟通到设计交付的协作能力"]', '["零基础想入门设计的爱好者","需要系统提升视觉能力的运营与产品人员","设计专业在校学生"]', '["自备可运行设计软件的电脑","具备基础的审美观察与临摹耐心"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/9ea21fed4fd5941eaa92c1fc4d1f4deeb82ba87b.jpg', '["设计创意","UI设计","平面设计","零基础学UI设计","即时设计软件教学","酸梅干超人出品"]', 13800, 8, 59159, '4.4', 9402, 'BV1NS4y1d7hC', NULL, NULL, NULL, 1, 0, 'standard', NULL, '酸梅干超人的电话亭', 0, 'tenant', 'published', '2021-11-04T12:52:09.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
