INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-8058766', 'course-bili-season-8058766', '100001', '0', 'BILI-DES-074', 'course-category-design', 'instructor-bili-3546902217886351', '一小时！激情原速讲解一下我手绘在画什么，视频价值一个亿，不看后悔！（手绘公开课3）', '10 讲完整课程 · 4 小时 53 分钟', '第一期：BV1F23mz2EUh 第二期：BV1B7gezNEKi 发端起于最近去了趟HF，手绘进度快了不少，有很多想讲的但是每一张都零零碎碎的，干脆变成连续剧，我没有任何准备以及刻意的想给大家讲什么 但至少继续爱发电', '课程简介：第一期：BV1F23mz2EUh 第二期：BV1B7gezNEKi 发端起于最近去了趟HF，手绘进度快了不少，有很多想讲的但是每一张都零零碎碎的，干脆变成连续剧，我没有任何准备以及刻意的想给大家讲什么 但至少继续爱发电也算我的职责了 最近助眠实在是没什么机会录制，但这种还是偶尔可以的 这里再向大伙道个歉，如果你真的看完了会发现观感并不好，1:噪音很大，当成自习白噪音不合格 2:语言退化，我结巴很多年，加上生平少说话，于是你会听到我说话有的字会重复念再讲下去，逻辑也不是很清晰 3:咳嗽 然后回到我想讲的东西上，这不是一个严格意义上的教学，这算一个思路分享，请吸收你觉得有道理的，如果你听到哪怕一点，你已学会并固定住的东西，不要怀疑自己，我十分鼓励大家保留自己的风格，权威和名声不是一切你值得点头的，我们都在学习，我们都是学生，我们都有自己的风格 如果有想问我的，欢迎评论区继续问，此视频只作开头作用，虽然是第三期但这确实只是刚刚开始，就没有讨论中心，我会收集大家的疑问，量足了下一期可以针对地分享一下，如果问题容易点破，我也许直接回答 最后，-陈皮- 课程结构：共 1 章 10 讲，累计时长 4 小时 53 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["掌握设计软件的核心操作与高效工作流","理解版式、色彩、字体与视觉层级的基本原理","独立完成一套可放入作品集的完整设计项目","建立从需求沟通到设计交付的协作能力"]', '["零基础想入门设计的爱好者","需要系统提升视觉能力的运营与产品人员","设计专业在校学生"]', '["自备可运行设计软件的电脑","具备基础的审美观察与临摹耐心"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/8c31db24a0db632ec141e417006cb25afd51d1c4.jpg', '["设计创意","UI设计","平面设计","furry绘画教程？","视频价值一个亿","不看后悔！"]', 17618, 10, 1390, '4.9', 713, 'BV1fHnF6SERs', NULL, NULL, NULL, 1, 0, 'standard', NULL, '月抛bot', 0, 'tenant', 'published', '2026-10-20T09:30:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
